"""wtask.duration —— ISO-8601 时长（Task Scheduler 风格）的解析与规范化。

接受的文本形如 ``P3D`` / ``PT72H`` / ``P1DT2H3M4S`` / ``PT0S``。
秒以外的部分必须是整数（本题不支持小数秒）。

规范形式（规格 §6）：先把总秒数分解成「天 / 时 / 分 / 秒」，只写非零分量，
时分秒全为 0 时省略整个 ``T`` 段，零时长写作 ``PT0S``。
因此 ``PT72H`` 的规范形式是 ``P3D``，``PT90M`` 的规范形式是 ``PT1H30M``。
"""

import re
from datetime import timedelta

from .errors import TaskDefError

_DUR_RE = re.compile(
    r"^P(?:(?P<d>\d+)D)?"
    r"(?:T(?:(?P<h>\d+)H)?(?:(?P<m>\d+)M)?(?:(?P<s>\d+)S)?)?$"
)


def parse_duration(text):
    """把 ISO-8601 时长文本解析为 ``datetime.timedelta``。

    非法文本抛 ``TaskDefError(kind="duration")``。
    """
    if not isinstance(text, str):
        raise TaskDefError("duration", "duration must be text, got %r" % (text,))
    raw = text.strip()
    if not raw:
        raise TaskDefError("duration", "empty duration")
    m = _DUR_RE.match(raw)
    if m is None:
        raise TaskDefError("duration", "invalid ISO-8601 duration: %r" % (text,))
    if raw in ("P", "PT"):
        raise TaskDefError("duration", "duration has no components: %r" % (text,))
    if "T" in raw and not (m.group("h") or m.group("m") or m.group("s")):
        # ``P1DT`` 之类的文本带了空的 T 段，不是合法时长。
        raise TaskDefError("duration", "duration has an empty time part: %r" % (text,))
    try:
        return timedelta(
            days=int(m.group("d") or 0),
            hours=int(m.group("h") or 0),
            minutes=int(m.group("m") or 0),
            seconds=int(m.group("s") or 0),
        )
    except (OverflowError, ValueError):
        raise TaskDefError("duration", "duration out of range: %r" % (text,))


def format_duration(value):
    """把 ``timedelta`` 写成规范 ISO-8601 文本（规格 §6）。

    先分解成天 / 时 / 分 / 秒，只写非零分量；时分秒全为 0 时省略 ``T`` 段；
    零时长写作 ``PT0S``。
    """
    if not isinstance(value, timedelta):
        raise TaskDefError("duration", "format_duration expects timedelta")
    if value < timedelta(0):
        raise TaskDefError("duration", "negative duration is not representable")
    total = int(value.total_seconds())
    if value != timedelta(seconds=total):
        # 不支持小数秒；丢弃亚秒信息会破坏「规范化序列化」的幂等性。
        raise TaskDefError("duration", "sub-second durations are not representable")
    if total == 0:
        return "PT0S"
    days, rest = divmod(total, 86400)
    hours, rest = divmod(rest, 3600)
    minutes, seconds = divmod(rest, 60)
    out = "P"
    if days:
        out += "%dD" % days
    if hours or minutes or seconds:
        out += "T"
        if hours:
            out += "%dH" % hours
        if minutes:
            out += "%dM" % minutes
        if seconds:
            out += "%dS" % seconds
    return out

"""wtask.schedule —— 触发时间计算。

本模块只做「给定任务与起始时刻，算出接下来的若干次运行时刻」这件事。
所有计算都在**本地 naive 时间**上进行（不涉及时区与夏令时）。

语义完全由 ``docs/TASKSCHEMA.md`` 决定：

* §3 四种日程（每日按 ``StartBoundary`` 锚定、每周按周一起始的周序号、
  月度按 ``Months`` / ``DaysOfMonth`` 过滤、``<Week>5</Week>`` 表示最后一周）；
* §4 主出现时刻取 ``StartBoundary`` 的时分秒，且不得早于 ``StartBoundary``、
  不得晚于 ``EndBoundary``；
* §5 ``Repetition`` 只保留满足 ``k×Interval < Duration`` 的那些时刻，
  重复同样受 ``EndBoundary`` 约束；
* §8 任务 / 触发器两级的启用开关，以及 ``next_runs`` / ``plan_window``
  的开闭区间与去重。
"""

import calendar
from datetime import date, datetime, time, timedelta

from .errors import TaskDefError

#: 主出现扫描的最大跨度（天）。
HORIZON_DAYS = 800

#: ``next_runs`` 向前搜索的最大跨度（天）——超过它仍找不到运行时刻就放弃。
MAX_SPAN_DAYS = 200 * 366

#: ``plan_window`` 一次最多枚举多少次运行（防御性上限，正常不会触及）。
PLAN_HARD_LIMIT = 20000

_MAX_DT = datetime(9999, 12, 31, 23, 59, 59)

_TRIGGER_TYPES = ("time", "daily", "weekly", "monthly", "monthly_dow")


# ------------------------------------------------------------------ 日历工具


def _as_datetime(value):
    """容忍 ``date`` 输入（按午夜处理）；其它类型原样返回。"""
    if isinstance(value, datetime) or not isinstance(value, date):
        return value
    return datetime.combine(value, time())


def _weekday_index(day):
    """Python 的 ``date.weekday()`` 是 Monday=0..Sunday=6；本模块统一用 Sunday=0。"""
    return (day.weekday() + 1) % 7


def _week_start(day):
    """返回 ``day`` 所在周的周一（规格 §3.2：周按周一起始划分）。"""
    return day - timedelta(days=day.weekday())


def _week_index(day):
    """``day`` 在本月内的「日历周」序号（1 起，规格 §3.4）。

    1–7 日为第 1 周，8–14 日为第 2 周，15–21 日为第 3 周，
    22–28 日为第 4 周，29 日及以后为第 5 周。
    """
    return (day.day - 1) // 7 + 1


def _weeks_in_month(day):
    """返回 ``day`` 所在月份共有多少个「日历周」（4 或 5）。"""
    days_in_month = calendar.monthrange(day.year, day.month)[1]
    return (days_in_month - 1) // 7 + 1


def _match_week(day, wanted):
    """``<Week>`` 匹配（规格 §3.4）。

    1..4 表示第 n 周；**5 表示该月的最后一周**——在只有 4 个日历周的月份
    （例如平年 2 月）里，``Week=5`` 匹配的是第 4 周。
    """
    index = _week_index(day)
    last = _weeks_in_month(day)
    for week in wanted:
        if week == index:
            return True
        if week == 5 and index == last:
            return True
    return False


def _positive(value, name):
    if not isinstance(value, int) or isinstance(value, bool) or value < 1:
        raise TaskDefError("range", "<%s> must be a positive integer, got %r" % (name, value))
    return value


def _day_matches(trigger, day):
    """``day`` 这一天是否是这个触发器的一个主出现日（不看时刻）。"""
    start_day = trigger.start.date()

    if trigger.type == "daily":
        interval = _positive(trigger.days_interval, "DaysInterval")
        # 锚点是 StartBoundary 的日期（规格 §3.1）。
        return (day - start_day).days % interval == 0

    if trigger.type == "weekly":
        if _weekday_index(day) not in trigger.days_of_week:
            return False
        interval = _positive(trigger.weeks_interval, "WeeksInterval")
        # 从 StartBoundary 所在的周算起，周序号差是 WeeksInterval 的整数倍。
        weeks = (_week_start(day) - _week_start(start_day)).days // 7
        return weeks % interval == 0

    if trigger.type == "monthly":
        if trigger.months and day.month not in trigger.months:
            return False
        return day.day in trigger.days_of_month

    if trigger.type == "monthly_dow":
        if trigger.months and day.month not in trigger.months:
            return False
        if _weekday_index(day) not in trigger.days_of_week:
            return False
        return _match_week(day, trigger.weeks_of_month)

    if trigger.type == "time":
        return day == start_day

    raise TaskDefError("trigger", "unknown trigger type: %r" % (trigger.type,))


# ------------------------------------------------------------------ 出现时刻


def _iter_primary(trigger, first_day, last_day):
    """产出 ``[first_day, last_day]`` 内的主出现时刻（升序，规格 §4）。

    时刻一律取 ``StartBoundary`` 的时分秒；早于 ``StartBoundary`` 的丢弃；
    一旦越过 ``EndBoundary`` 立即停止（主出现时刻随日期单调递增）。
    """
    day = max(first_day, trigger.start.date())
    tod = trigger.start.time()
    end = trigger.end
    while day <= last_day:
        if _day_matches(trigger, day):
            moment = datetime.combine(day, tod)
            if moment >= trigger.start:
                if end is not None and moment > end:
                    return
                yield moment
        day += timedelta(days=1)


def _iter_runs(trigger, occurrence, lo=None, hi=None, limit=None):
    """把一次主出现展开为若干次实际运行（规格 §5），升序产出。

    * 没有 ``Repetition`` 时只有主出现本身；
    * 否则为 ``occurrence + k×Interval``（k = 0, 1, 2, …），只保留
      ``k×Interval < Duration`` 的那些（``Duration`` 缺省表示不限时长）；
    * 任何时刻都不得越过 ``EndBoundary``；
    * ``lo`` / ``hi`` / ``limit`` 只是枚举边界，不影响上述语义。
    """
    end = trigger.end
    repetition = trigger.repetition

    if repetition is None:
        if end is not None and occurrence > end:
            return
        if lo is not None and occurrence <= lo:
            return
        if hi is not None and occurrence > hi:
            return
        yield occurrence
        return

    interval = repetition.interval
    if interval <= timedelta(0):
        raise TaskDefError("range", "repetition <Interval> must be positive")
    duration = repetition.duration

    step = 0
    if lo is not None and occurrence <= lo:
        # 直接跳到第一个大于 lo 的步数，避免逐格空转。
        step = (lo - occurrence) // interval + 1
    produced = 0
    while True:
        if limit is not None and produced >= limit:
            return
        offset = interval * step
        if duration is not None and offset >= duration:
            return
        moment = occurrence + offset
        if end is not None and moment > end:
            return
        if hi is not None and moment > hi:
            return
        yield moment
        produced += 1
        step += 1


def _lookback_start(trigger, moment):
    """最早还需要考察的主出现日。

    主出现本身早于 ``moment`` 也可能通过 ``Repetition`` 在 ``moment`` 之后
    产生运行时刻，因此要往前多看一段。
    """
    repetition = trigger.repetition
    if repetition is None:
        return moment.date()
    if repetition.duration is None:
        # 不限时长：从起点开始的所有主出现都还可能贡献运行时刻。
        return trigger.start.date()
    return (moment - repetition.duration).date()


def _collect_trigger(trigger, lo, hi, limit, out):
    """把 ``trigger`` 位于 ``(lo, hi]`` 内的运行时刻收进 ``out``。"""
    last_day = hi.date()
    if trigger.end is not None and trigger.end.date() < last_day:
        last_day = trigger.end.date()
    first_day = _lookback_start(trigger, lo)
    for occurrence in _iter_primary(trigger, first_day, last_day):
        for moment in _iter_runs(trigger, occurrence, lo=lo, hi=hi, limit=limit):
            out.add(moment)


def _add_days(moment, days):
    try:
        value = moment + timedelta(days=days)
    except OverflowError:
        return _MAX_DT
    if value > _MAX_DT:
        return _MAX_DT
    return value


# ------------------------------------------------------------------ 公共 API


def next_runs(task, after, count):
    """返回 ``after`` 之后最近的 ``count`` 次运行时刻（升序、去重）。

    * 任务被禁用（``task.enabled`` 为假）时返回空列表；
    * 触发器被禁用（``trigger.enabled`` 为假）时跳过该触发器；
    * 返回的时刻**严格大于** ``after``；不足 ``count`` 次时返回实际数量。
    """
    if not task.enabled:
        return []
    if count is None:
        return []
    try:
        count = int(count)
    except (TypeError, ValueError):
        raise TaskDefError("range", "count must be an integer: %r" % (count,))
    if count <= 0:
        return []

    after = _as_datetime(after)
    triggers = [trigger for trigger in task.triggers if trigger.enabled]
    if not triggers:
        return []

    # 起点在很远的将来时，先把窗口推到起点附近，避免无谓的逐日扫描。
    window = HORIZON_DAYS
    earliest_start = min(trigger.start for trigger in triggers)
    if earliest_start > after:
        window = max(window, (earliest_start - after).days + HORIZON_DAYS)

    # 所有触发器都有 EndBoundary 时，运行时刻总数有限，可以算出封顶跨度。
    cover = None
    if all(trigger.end is not None for trigger in triggers):
        latest_end = max(trigger.end for trigger in triggers)
        cover = (latest_end - after).days + 2

    while True:
        hi = _add_days(after, window)
        moments = set()
        for trigger in triggers:
            _collect_trigger(trigger, after, hi, count, moments)
        result = sorted(moments)[:count]
        if len(result) >= count:
            return result
        if cover is not None and window >= cover:
            return result
        if hi >= _MAX_DT or window >= MAX_SPAN_DAYS:
            return result
        window *= 8


def plan_window(task, start, end):
    """返回位于 ``(start, end]`` 区间内的全部运行时刻（升序、去重）。"""
    if not task.enabled:
        return []
    start = _as_datetime(start)
    end = _as_datetime(end)
    if end <= start:
        return []

    moments = set()
    for trigger in task.triggers:
        if not trigger.enabled:
            continue
        _collect_trigger(trigger, start, end, None, moments)
    return sorted(moments)


# ------------------------------------------------------------------ 校验


def _check_range(value, low, high, name):
    if not isinstance(value, int) or isinstance(value, bool) or not low <= value <= high:
        raise TaskDefError("range", "<%s> %r out of %d..%d" % (name, value, low, high))


def _validate_trigger(trigger):
    if trigger.end is not None and trigger.end < trigger.start:
        raise TaskDefError(
            "structure",
            "EndBoundary %s is earlier than StartBoundary %s"
            % (trigger.end.isoformat(), trigger.start.isoformat()),
        )
    if trigger.type not in _TRIGGER_TYPES:
        raise TaskDefError("trigger", "unknown trigger type: %r" % (trigger.type,))

    if trigger.type == "daily":
        _check_range(trigger.days_interval, 1, 365, "DaysInterval")
    elif trigger.type == "weekly":
        _check_range(trigger.weeks_interval, 1, 52, "WeeksInterval")
        if not trigger.days_of_week:
            raise TaskDefError("trigger", "<DaysOfWeek> is empty")
        for day in trigger.days_of_week:
            _check_range(day, 0, 6, "DayOfWeek")
    elif trigger.type == "monthly":
        if not trigger.days_of_month:
            raise TaskDefError("trigger", "<DaysOfMonth> is empty")
        for day in trigger.days_of_month:
            _check_range(day, 1, 31, "Day")
        for month in trigger.months:
            _check_range(month, 1, 12, "Month")
    elif trigger.type == "monthly_dow":
        if not trigger.weeks_of_month:
            raise TaskDefError("trigger", "<Weeks> is empty")
        for week in trigger.weeks_of_month:
            _check_range(week, 1, 5, "Week")
        if not trigger.days_of_week:
            raise TaskDefError("trigger", "<DaysOfWeek> is empty")
        for day in trigger.days_of_week:
            _check_range(day, 0, 6, "DayOfWeek")
        for month in trigger.months:
            _check_range(month, 1, 12, "Month")

    repetition = trigger.repetition
    if repetition is not None and repetition.interval <= timedelta(0):
        raise TaskDefError("range", "repetition <Interval> must be positive")


def validate_task(task):
    """跨字段一致性校验；不一致时抛 ``TaskDefError``。"""
    for trigger in task.triggers:
        _validate_trigger(trigger)
    return task

"""wtask.schedule —— 触发时间计算。

本模块只做「给定任务与起始时刻，算出接下来的若干次运行时刻」这件事。
所有计算都在**本地 naive 时间**上进行（不涉及时区与夏令时）。

语义完全由 ``docs/TASKSCHEMA.md`` 决定：

* §3 四种日程（每日按 ``StartBoundary`` 锚定、每周按周一起始的周序号、
  月度按 ``Months`` / ``DaysOfMonth`` 过滤、``<Week>5</Week>`` 表示最后一周）；
* §4 主出现时刻取 ``StartBoundary`` 的时分秒，且不得早于 ``StartBoundary``、
  不得晚于 ``EndBoundary``；
* §5 ``Repetition`` 只保留满足 ``k×Interval < Duration`` 的那些时刻，
  重复同样受 ``EndBoundary`` 约束；
* §8 任务 / 触发器两级的启用开关，以及 ``next_runs`` / ``plan_window``
  的开闭区间与去重。
"""

import calendar
from datetime import date, datetime, time, timedelta

from .errors import TaskDefError

#: 主出现扫描的最大跨度（天）。
HORIZON_DAYS = 800

#: ``next_runs`` 向前搜索的最大跨度（天）——超过它仍找不到运行时刻就放弃。
MAX_SPAN_DAYS = 200 * 366

#: ``plan_window`` 一次最多枚举多少次运行（防御性上限，正常不会触及）。
PLAN_HARD_LIMIT = 20000

_MAX_DT = datetime(9999, 12, 31, 23, 59, 59)

_TRIGGER_TYPES = ("time", "daily", "weekly", "monthly", "monthly_dow")


# ------------------------------------------------------------------ 日历工具


def _as_datetime(value):
    """容忍 ``date`` 输入（按午夜处理）；其它类型原样返回。"""
    if isinstance(value, datetime) or not isinstance(value, date):
        return value
    return datetime.combine(value, time())


def _weekday_index(day):
    """Python 的 ``date.weekday()`` 是 Monday=0..Sunday=6；本模块统一用 Sunday=0。"""
    return (day.weekday() + 1) % 7


def _week_start(day):
    """返回 ``day`` 所在周的周一（规格 §3.2：周按周一起始划分）。"""
    return day - timedelta(days=day.weekday())


def _week_index(day):
    """``day`` 在本月内的「日历周」序号（1 起，规格 §3.4）。

    1–7 日为第 1 周，8–14 日为第 2 周，15–21 日为第 3 周，
    22–28 日为第 4 周，29 日及以后为第 5 周。
    """
    return (day.day - 1) // 7 + 1


def _weeks_in_month(day):
    """返回 ``day`` 所在月份共有多少个「日历周」（4 或 5）。"""
    days_in_month = calendar.monthrange(day.year, day.month)[1]
    return (days_in_month - 1) // 7 + 1


def _match_week(day, wanted):
    """``<Week>`` 匹配（规格 §3.4）。

    1..4 表示第 n 周；**5 表示该月的最后一周**——在只有 4 个日历周的月份
    （例如平年 2 月）里，``Week=5`` 匹配的是第 4 周。
    """
    index = _week_index(day)
    last = _weeks_in_month(day)
    for week in wanted:
        if week == index:
            return True
        if week == 5 and index == last:
            return True
    return False


def _check_range(value, low, high, name):
    if not isinstance(value, int) or isinstance(value, bool) or not low <= value <= high:
        raise TaskDefError("range", "<%s> %r out of %d..%d" % (name, value, low, high))


def _day_matches(trigger, day):
    """``day`` 这一天是否是这个触发器的一个主出现日（不看时刻）。"""
    start_day = trigger.start.date()

    if trigger.type == "daily":
        interval = trigger.days_interval
        _check_range(interval, 1, 365, "DaysInterval")
        # 锚点是 StartBoundary 的日期（规格 §3.1）。
        return (day - start_day).days % interval == 0

    if trigger.type == "weekly":
        if _weekday_index(day) not in trigger.days_of_week:
            return False
        interval = trigger.weeks_interval
        _check_range(interval, 1, 52, "WeeksInterval")
        # 从 StartBoundary 所在的周算起，周序号差是 WeeksInterval 的整数倍。
        weeks = (_week_start(day) - _week_start(start_day)).days // 7
        return weeks % interval == 0

    if trigger.type == "monthly":
        if trigger.months and day.month not in trigger.months:
            return False
        return day.day in trigger.days_of_month

    if trigger.type == "monthly_dow":
        if trigger.months and day.month not in trigger.months:
            return False
        if _weekday_index(day) not in trigger.days_of_week:
            return False
        return _match_week(day, trigger.weeks_of_month)

    if trigger.type == "time":
        return day == start_day

    raise TaskDefError("trigger", "unknown trigger type: %r" % (trigger.type,))


# ------------------------------------------------------------------ 出现时刻


def _iter_primary(trigger, first_day, last_day):
    """产出 ``[first_day, last_day]`` 内的主出现时刻（升序，规格 §4）。

    时刻一律取 ``StartBoundary`` 的时分秒；早于 ``StartBoundary`` 的丢弃；
    一旦越过 ``EndBoundary`` 立即停止（主出现时刻随日期单调递增）。
    """
    day = max(first_day, trigger.start.date())
    tod = trigger.start.time()
    end = trigger.end
    while day <= last_day:
        if _day_matches(trigger, day):
            moment = datetime.combine(day, tod)
            if moment >= trigger.start:
                if end is not None and moment > end:
                    return
                yield moment
        day += timedelta(days=1)


def _iter_runs(trigger, occurrence, lo=None, hi=None, limit=None):
    """把一次主出现展开为若干次实际运行（规格 §5），升序产出。

    * 没有 ``Repetition`` 时只有主出现本身；
    * 否则为 ``occurrence + k×Interval``（k = 0, 1, 2, …），只保留
      ``k×Interval < Duration`` 的那些（``Duration`` 缺省表示不限时长）；
    * 任何时刻都不得越过 ``EndBoundary``；
    * ``lo`` / ``hi`` / ``limit`` 只是枚举边界，不影响上述语义。
    """
    end = trigger.end
    repetition = trigger.repetition

    if repetition is None:
        if end is not None and occurrence > end:
            return
        if lo is not None and occurrence <= lo:
            return
        if hi is not None and occurrence > hi:
            return
        yield occurrence
        return

    interval = repetition.interval
    if interval <= timedelta(0):
        raise TaskDefError("range", "repetition <Interval> must be positive")
    duration = repetition.duration

    step = 0
    if lo is not None and occurrence <= lo:
        # 直接跳到第一个大于 lo 的步数，避免逐格空转。
        step = (lo - occurrence) // interval + 1
    produced = 0
    while True:
        if limit is not None and produced >= limit:
            return
        offset = interval * step
        if duration is not None and offset >= duration:
            return
        moment = occurrence + offset
        if end is not None and moment > end:
            return
        if hi is not None and moment > hi:
            return
        yield moment
        produced += 1
        step += 1


def _lookback_start(trigger, moment):
    """最早还需要考察的主出现日。

    主出现本身早于 ``moment`` 也可能通过 ``Repetition`` 在 ``moment`` 之后
    产生运行时刻，因此要往前多看一段。
    """
    repetition = trigger.repetition
    if repetition is None:
        return moment.date()
    if repetition.duration is None:
        # 不限时长：从起点开始的所有主出现都还可能贡献运行时刻。
        return trigger.start.date()
    return (moment - repetition.duration).date()


def _collect_trigger(trigger, lo, hi, limit, out):
    """把 ``trigger`` 位于 ``(lo, hi]`` 内的运行时刻收进 ``out``。

    ``limit`` 限制**单次主出现**最多贡献多少个时刻；由于调用方最终只要
    全体时刻里最小的 ``limit`` 个，这个截断不会丢掉任何需要的时刻。
    """
    last_day = hi.date()
    if trigger.end is not None and trigger.end.date() < last_day:
        last_day = trigger.end.date()
    first_day = _lookback_start(trigger, lo)
    for occurrence in _iter_primary(trigger, first_day, last_day):
        for moment in _iter_runs(trigger, occurrence, lo=lo, hi=hi, limit=limit):
            out.add(moment)


def _add_days(moment, days):
    try:
        value = moment + timedelta(days=days)
    except OverflowError:
        return _MAX_DT
    if value > _MAX_DT:
        return _MAX_DT
    return value


# ------------------------------------------------------------------ 公共 API


def next_runs(task, after, count):
    """返回 ``after`` 之后最近的 ``count`` 次运行时刻（升序、去重）。

    * 任务被禁用（``task.enabled`` 为假）时返回空列表；
    * 触发器被禁用（``trigger.enabled`` 为假）时跳过该触发器；
    * 返回的时刻**严格大于** ``after``；不足 ``count`` 次时返回实际数量。
    """
    if not task.enabled:
        return []
    if count is None:
        return []
    try:
        count = int(count)
    except (TypeError, ValueError):
        raise TaskDefError("range", "count must be an integer: %r" % (count,))
    if count <= 0:
        return []

    after = _as_datetime(after)
    triggers = [trigger for trigger in task.triggers if trigger.enabled]
    if not triggers:
        return []

    # 起点在很远的将来时，先把窗口推到起点附近，避免无谓的逐日扫描。
    earliest_start = min(trigger.start for trigger in triggers)
    lead = 0
    window = HORIZON_DAYS
    if earliest_start > after:
        lead = (earliest_start - after).days
        window = max(window, lead + HORIZON_DAYS)
    max_span = MAX_SPAN_DAYS + lead

    # 所有触发器都有 EndBoundary 时，运行时刻总数有限，可以算出封顶跨度。
    cover = None
    if all(trigger.end is not None for trigger in triggers):
        latest_end = max(trigger.end for trigger in triggers)
        cover = (latest_end - after).days + 2
        max_span = min(max_span, max(cover, HORIZON_DAYS))

    while True:
        hi = _add_days(after, window)
        moments = set()
        for trigger in triggers:
            _collect_trigger(trigger, after, hi, count, moments)
        result = sorted(moments)[:count]
        if len(result) >= count:
            return result
        if cover is not None and window >= cover:
            # 有限的运行时刻已经全部枚举完。
            return result
        if window >= max_span or hi >= _MAX_DT:
            return result
        window = min(window * 8, max_span)


def plan_window(task, start, end):
    """返回位于 ``(start, end]`` 区间内的全部运行时刻（升序、去重）。"""
    if not task.enabled:
        return []
    start = _as_datetime(start)
    end = _as_datetime(end)
    if end <= start:
        return []

    moments = set()
    for trigger in task.triggers:
        if not trigger.enabled:
            continue
        _collect_trigger(trigger, start, end, None, moments)
    return sorted(moments)


# ------------------------------------------------------------------ 校验


def _validate_trigger(trigger):
    if trigger.end is not None and trigger.end < trigger.start:
        raise TaskDefError(
            "structure",
            "EndBoundary %s is earlier than StartBoundary %s"
            % (trigger.end.isoformat(), trigger.start.isoformat()),
        )
    if trigger.type not in _TRIGGER_TYPES:
        raise TaskDefError("trigger", "unknown trigger type: %r" % (trigger.type,))

    if trigger.type == "daily":
        _check_range(trigger.days_interval, 1, 365, "DaysInterval")
    elif trigger.type == "weekly":
        _check_range(trigger.weeks_interval, 1, 52, "WeeksInterval")
        if not trigger.days_of_week:
            raise TaskDefError("trigger", "<DaysOfWeek> is empty")
        for day in trigger.days_of_week:
            _check_range(day, 0, 6, "DayOfWeek")
    elif trigger.type == "monthly":
        if not trigger.days_of_month:
            raise TaskDefError("trigger", "<DaysOfMonth> is empty")
        for day in trigger.days_of_month:
            _check_range(day, 1, 31, "Day")
        for month in trigger.months:
            _check_range(month, 1, 12, "Month")
    elif trigger.type == "monthly_dow":
        if not trigger.weeks_of_month:
            raise TaskDefError("trigger", "<Weeks> is empty")
        for week in trigger.weeks_of_month:
            _check_range(week, 1, 5, "Week")
        if not trigger.days_of_week:
            raise TaskDefError("trigger", "<DaysOfWeek> is empty")
        for day in trigger.days_of_week:
            _check_range(day, 0, 6, "DayOfWeek")
        for month in trigger.months:
            _check_range(month, 1, 12, "Month")

    repetition = trigger.repetition
    if repetition is not None and repetition.interval <= timedelta(0):
        raise TaskDefError("range", "repetition <Interval> must be positive")


def validate_task(task):
    """跨字段一致性校验；不一致时抛 ``TaskDefError``。"""
    for trigger in task.triggers:
        _validate_trigger(trigger)
    return task

"""wtask.xmlio —— 任务 XML 的解析与规范化序列化。

解析负责把文本变成 :class:`~wtask.model.Task`，并按 ``docs/TASKSCHEMA.md`` §9
把所有结构 / 取值问题归类成 ``TaskDefError``；序列化负责输出 §7 要求的
规范化文本（元素顺序固定、缺省值省略、时长写规范形式），并保证幂等。
"""

import re
import xml.etree.ElementTree as ET
from datetime import datetime, timedelta

from .duration import format_duration, parse_duration
from .errors import TaskDefError
from .model import MONTH_NAMES, WEEKDAY_NAMES, Repetition, Task, Trigger
from .schedule import validate_task

#: 受支持的 ``version`` 属性
SUPPORTED_VERSIONS = ("1.0", "1.2")

#: 默认命名空间（序列化时写回）
NS = "http://schemas.microsoft.com/windows/2004/02/mit/task"

DATETIME_FORMAT = "%Y-%m-%dT%H:%M:%S"

_DEFAULT_MULTIPLE_INSTANCES = "IgnoreNew"

_TRIGGER_TAGS = ("CalendarTrigger", "TimeTrigger")
_SCHEDULE_TAGS = (
    "ScheduleByDay",
    "ScheduleByWeek",
    "ScheduleByMonth",
    "ScheduleByMonthDayOfWeek",
)
_CALENDAR_ALLOWED = ("StartBoundary", "EndBoundary", "Enabled", "Repetition") + _SCHEDULE_TAGS
_TIME_ALLOWED = ("StartBoundary", "EndBoundary", "Enabled", "Repetition")
_REPETITION_ALLOWED = ("Interval", "Duration", "StopAtDurationEnd")
_SETTINGS_ALLOWED = (
    "MultipleInstancesPolicy",
    "Enabled",
    "ExecutionTimeLimit",
    "RandomDelay",
)

_INT_RE = re.compile(r"^[+-]?\d+$")


# ------------------------------------------------------------------ 解析工具


def _tag(element):
    """去掉命名空间前缀，返回本地标签名。"""
    tag = element.tag
    return tag.split("}", 1)[1] if "}" in tag else tag


def _children(element, name):
    return [child for child in element if _tag(child) == name]


def _one(element, name):
    found = _children(element, name)
    if len(found) > 1:
        raise TaskDefError("schema", "duplicate <%s>" % name)
    return found[0] if found else None


def _text(element, name, required=False):
    child = _one(element, name)
    if child is None:
        if required:
            raise TaskDefError("schema", "missing required <%s>" % name)
        return None
    return (child.text or "").strip()


def _parse_datetime(text, name):
    """解析 ``YYYY-MM-DDTHH:MM:SS``（本地 naive 时间，规格 §2）。"""
    try:
        value = datetime.strptime(text, DATETIME_FORMAT)
    except (TypeError, ValueError):
        raise TaskDefError("range", "invalid datetime in <%s>: %r" % (name, text))
    canonical = "%04d-%02d-%02dT%02d:%02d:%02d" % (
        value.year, value.month, value.day, value.hour, value.minute, value.second,
    )
    if canonical != text:
        raise TaskDefError("range", "non-canonical datetime in <%s>: %r" % (name, text))
    return value


def _parse_bool(text, name):
    value = (text or "").strip().lower()
    if value in ("true", "1"):
        return True
    if value in ("false", "0"):
        return False
    raise TaskDefError("range", "invalid boolean in <%s>: %r" % (name, text))


def _parse_int(text, name):
    if not isinstance(text, str):
        text = "" if text is None else text
        text = text.strip() if isinstance(text, str) else text
    raw = text.strip() if isinstance(text, str) else text
    if not isinstance(raw, str) or not _INT_RE.match(raw):
        raise TaskDefError("range", "invalid integer in <%s>: %r" % (name, text))
    return int(raw)


def _check_children(element, allowed, where):
    for child in element:
        if _tag(child) not in allowed:
            raise TaskDefError("trigger", "unexpected <%s> inside <%s>" % (_tag(child), where))


def _parse_weekdays(element, name):
    """解析 ``<DaysOfWeek><Monday/>…</DaysOfWeek>``；缺失时返回 ``None``。"""
    holder = _one(element, name)
    if holder is None:
        return None
    days = []
    for child in holder:
        local = _tag(child)
        if local not in WEEKDAY_NAMES:
            raise TaskDefError("trigger", "unknown weekday <%s>" % local)
        days.append(WEEKDAY_NAMES.index(local))
    if not days:
        raise TaskDefError("trigger", "<%s> is empty" % name)
    if len(set(days)) != len(days):
        raise TaskDefError("trigger", "duplicate weekday in <%s>" % name)
    return tuple(sorted(days))


def _parse_months(element):
    holder = _one(element, "Months")
    if holder is None:
        raise TaskDefError("schema", "missing required <Months>")
    months = []
    for child in holder:
        local = _tag(child)
        if local not in MONTH_NAMES:
            raise TaskDefError("trigger", "unknown month <%s>" % local)
        months.append(MONTH_NAMES.index(local) + 1)
    if not months:
        raise TaskDefError("trigger", "<Months> is empty")
    if len(set(months)) != len(months):
        raise TaskDefError("trigger", "duplicate month in <Months>")
    return tuple(sorted(months))


def _parse_number_list(holder, tag_name, field_name, low, high):
    """解析 ``<Holder><Tag>1</Tag>…</Holder>`` 里的整数列表。"""
    values = []
    for child in holder:
        if _tag(child) != tag_name:
            raise TaskDefError(
                "trigger", "unexpected <%s> inside <%s>" % (_tag(child), field_name)
            )
        value = _parse_int(child.text, tag_name)
        if not low <= value <= high:
            raise TaskDefError("range", "<%s> %d out of %d..%d" % (tag_name, value, low, high))
        values.append(value)
    if not values:
        raise TaskDefError("trigger", "<%s> is empty" % field_name)
    return tuple(sorted(values))


def _parse_repetition(holder):
    element = _one(holder, "Repetition")
    if element is None:
        return None
    _check_children(element, _REPETITION_ALLOWED, "Repetition")

    interval_text = _text(element, "Interval", required=True)
    interval = parse_duration(interval_text)
    if interval <= timedelta(0):
        raise TaskDefError("range", "repetition <Interval> must be positive")

    duration_text = _text(element, "Duration")
    duration = parse_duration(duration_text) if duration_text is not None else None
    if duration is not None and duration <= timedelta(0):
        raise TaskDefError("range", "repetition <Duration> must be positive")

    stop_text = _text(element, "StopAtDurationEnd")
    stop = _parse_bool(stop_text, "StopAtDurationEnd") if stop_text is not None else False
    return Repetition(interval=interval, duration=duration, stop_at_duration_end=stop)


def _parse_common(element):
    """``StartBoundary`` / ``EndBoundary`` / ``Enabled`` / ``Repetition``。"""
    start = _parse_datetime(_text(element, "StartBoundary", required=True), "StartBoundary")
    end_text = _text(element, "EndBoundary")
    end = _parse_datetime(end_text, "EndBoundary") if end_text is not None else None
    enabled_text = _text(element, "Enabled")
    enabled = _parse_bool(enabled_text, "Enabled") if enabled_text is not None else True
    return start, end, enabled, _parse_repetition(element)


def _parse_calendar(element):
    _check_children(element, _CALENDAR_ALLOWED, "CalendarTrigger")
    start, end, enabled, repetition = _parse_common(element)

    schedules = [child for child in element if _tag(child) in _SCHEDULE_TAGS]
    if not schedules:
        raise TaskDefError("trigger", "<CalendarTrigger> requires exactly one schedule")
    if len(schedules) > 1:
        raise TaskDefError(
            "trigger", "<CalendarTrigger> has %d schedules, expected 1" % len(schedules)
        )
    schedule = schedules[0]
    kind = _tag(schedule)

    if kind == "ScheduleByDay":
        _check_children(schedule, ("DaysInterval",), "ScheduleByDay")
        interval_text = _text(schedule, "DaysInterval")
        if interval_text is None:
            days_interval = 1
        else:
            days_interval = _parse_int(interval_text, "DaysInterval")
            if not 1 <= days_interval <= 365:
                raise TaskDefError("range", "DaysInterval %d out of 1..365" % days_interval)
        return Trigger(
            type="daily", start=start, end=end, enabled=enabled,
            days_interval=days_interval, repetition=repetition,
        )

    if kind == "ScheduleByWeek":
        _check_children(schedule, ("DaysOfWeek", "WeeksInterval"), "ScheduleByWeek")
        days_of_week = _parse_weekdays(schedule, "DaysOfWeek")
        if days_of_week is None:
            raise TaskDefError("trigger", "<ScheduleByWeek> requires <DaysOfWeek>")
        weeks_text = _text(schedule, "WeeksInterval")
        if weeks_text is None:
            weeks_interval = 1
        else:
            weeks_interval = _parse_int(weeks_text, "WeeksInterval")
            if not 1 <= weeks_interval <= 52:
                raise TaskDefError("range", "WeeksInterval %d out of 1..52" % weeks_interval)
        return Trigger(
            type="weekly", start=start, end=end, enabled=enabled,
            weeks_interval=weeks_interval, days_of_week=days_of_week,
            repetition=repetition,
        )

    if kind == "ScheduleByMonth":
        _check_children(schedule, ("DaysOfMonth", "Months"), "ScheduleByMonth")
        holder = _one(schedule, "DaysOfMonth")
        if holder is None:
            raise TaskDefError("schema", "missing required <DaysOfMonth>")
        days_of_month = _parse_number_list(holder, "Day", "DaysOfMonth", 1, 31)
        return Trigger(
            type="monthly", start=start, end=end, enabled=enabled,
            days_of_month=days_of_month, months=_parse_months(schedule),
            repetition=repetition,
        )

    # ScheduleByMonthDayOfWeek
    _check_children(schedule, ("Weeks", "DaysOfWeek", "Months"), "ScheduleByMonthDayOfWeek")
    holder = _one(schedule, "Weeks")
    if holder is None:
        raise TaskDefError("schema", "missing required <Weeks>")
    weeks_of_month = _parse_number_list(holder, "Week", "Weeks", 1, 5)
    days_of_week = _parse_weekdays(schedule, "DaysOfWeek")
    if days_of_week is None:
        raise TaskDefError("trigger", "<ScheduleByMonthDayOfWeek> requires <DaysOfWeek>")
    return Trigger(
        type="monthly_dow", start=start, end=end, enabled=enabled,
        days_of_week=days_of_week, weeks_of_month=weeks_of_month,
        months=_parse_months(schedule), repetition=repetition,
    )


def _parse_time(element):
    _check_children(element, _TIME_ALLOWED, "TimeTrigger")
    start, end, enabled, repetition = _parse_common(element)
    return Trigger(type="time", start=start, end=end, enabled=enabled, repetition=repetition)


def _parse_settings(element, fields):
    for child in element:
        local = _tag(child)
        if local not in _SETTINGS_ALLOWED:
            # 规格 §1 只约定了 Settings 的可取子元素，未把未知子元素列为错误。
            continue
        if local == "Enabled":
            fields["enabled"] = _parse_bool((child.text or "").strip(), "Enabled")
        elif local == "ExecutionTimeLimit":
            limit = parse_duration((child.text or "").strip())
            # 规格 §1：``PT0S`` 等于「不限」。
            fields["execution_time_limit"] = limit if limit > timedelta(0) else None
        elif local == "RandomDelay":
            fields["random_delay"] = parse_duration((child.text or "").strip())
        elif local == "MultipleInstancesPolicy":
            policy = (child.text or "").strip()
            if policy:
                fields["multiple_instances"] = policy


# ------------------------------------------------------------------ 公共 API


def parse_task_xml(text):
    """把任务 XML 解析为 :class:`~wtask.model.Task`。"""
    if not isinstance(text, (str, bytes)):
        raise TaskDefError("xml", "text must be str or bytes")
    try:
        root = ET.fromstring(text)
    except ET.ParseError as exc:
        raise TaskDefError("xml", str(exc))
    except ValueError as exc:
        raise TaskDefError("xml", str(exc))

    if _tag(root) != "Task":
        raise TaskDefError("schema", "root element must be <Task>")

    version = (root.get("version") or "").strip()
    if version not in SUPPORTED_VERSIONS:
        raise TaskDefError(
            "version", "unsupported version %r (expected one of %s)"
            % (version, ", ".join(SUPPORTED_VERSIONS))
        )

    holders = _children(root, "Triggers")
    if not holders:
        raise TaskDefError("structure", "missing <Triggers>")
    if len(holders) > 1:
        raise TaskDefError("schema", "duplicate <Triggers>")

    triggers = []
    for child in holders[0]:
        local = _tag(child)
        if local == "CalendarTrigger":
            triggers.append(_parse_calendar(child))
        elif local == "TimeTrigger":
            triggers.append(_parse_time(child))
        else:
            # 规格 §2：``<Triggers>`` 下只允许这两种触发器。
            raise TaskDefError("trigger", "unknown trigger <%s> inside <Triggers>" % local)
    if not triggers:
        raise TaskDefError("structure", "<Triggers> is empty")

    fields = {"version": version, "triggers": tuple(triggers)}
    settings = _one(root, "Settings")
    if settings is not None:
        _parse_settings(settings, fields)

    task = Task(**fields)
    validate_task(task)
    return task


def _format_datetime(value):
    return value.strftime(DATETIME_FORMAT)


def _weekday_elements(days):
    return "".join("<%s/>" % WEEKDAY_NAMES[day] for day in days)


def _month_elements(months):
    return "".join("<%s/>" % MONTH_NAMES[month - 1] for month in months)


def _trigger_xml(trigger, indent):
    pad = " " * indent
    inner = " " * (indent + 2)
    if trigger.type == "time":
        name = "TimeTrigger"
    elif trigger.type in ("daily", "weekly", "monthly", "monthly_dow"):
        name = "CalendarTrigger"
    else:
        raise TaskDefError("trigger", "unknown trigger type: %r" % (trigger.type,))

    lines = [pad + "<%s>" % name]
    lines.append(inner + "<StartBoundary>%s</StartBoundary>" % _format_datetime(trigger.start))
    if trigger.end is not None:
        lines.append(inner + "<EndBoundary>%s</EndBoundary>" % _format_datetime(trigger.end))
    if not trigger.enabled:
        lines.append(inner + "<Enabled>false</Enabled>")

    if trigger.type == "daily":
        lines.append(inner + "<ScheduleByDay>")
        lines.append(inner + "  <DaysInterval>%d</DaysInterval>" % trigger.days_interval)
        lines.append(inner + "</ScheduleByDay>")
    elif trigger.type == "weekly":
        lines.append(inner + "<ScheduleByWeek>")
        lines.append(
            inner + "  <DaysOfWeek>" + _weekday_elements(trigger.days_of_week) + "</DaysOfWeek>"
        )
        lines.append(inner + "  <WeeksInterval>%d</WeeksInterval>" % trigger.weeks_interval)
        lines.append(inner + "</ScheduleByWeek>")
    elif trigger.type == "monthly":
        lines.append(inner + "<ScheduleByMonth>")
        lines.append(
            inner + "  <DaysOfMonth>"
            + "".join("<Day>%d</Day>" % day for day in trigger.days_of_month)
            + "</DaysOfMonth>"
        )
        lines.append(inner + "  <Months>" + _month_elements(trigger.months) + "</Months>")
        lines.append(inner + "</ScheduleByMonth>")
    elif trigger.type == "monthly_dow":
        lines.append(inner + "<ScheduleByMonthDayOfWeek>")
        lines.append(
            inner + "  <Weeks>"
            + "".join("<Week>%d</Week>" % week for week in trigger.weeks_of_month)
            + "</Weeks>"
        )
        lines.append(
            inner + "  <DaysOfWeek>" + _weekday_elements(trigger.days_of_week) + "</DaysOfWeek>"
        )
        lines.append(inner + "  <Months>" + _month_elements(trigger.months) + "</Months>")
        lines.append(inner + "</ScheduleByMonthDayOfWeek>")

    repetition = trigger.repetition
    if repetition is not None:
        lines.append(inner + "<Repetition>")
        lines.append(inner + "  <Interval>%s</Interval>" % format_duration(repetition.interval))
        if repetition.duration is not None:
            lines.append(
                inner + "  <Duration>%s</Duration>" % format_duration(repetition.duration)
            )
        if repetition.stop_at_duration_end:
            lines.append(inner + "  <StopAtDurationEnd>true</StopAtDurationEnd>")
        lines.append(inner + "</Repetition>")

    lines.append(pad + "</%s>" % name)
    return lines


def task_to_xml(task):
    """把 :class:`~wtask.model.Task` 规范化为 XML 文本。

    规范化规则见 ``docs/TASKSCHEMA.md`` §7：元素与属性顺序固定、缺省值省略、
    日期时间写作 ``YYYY-MM-DDTHH:MM:SS``、时长写成规范形式。
    """
    lines = ['<Task version="%s" xmlns="%s">' % (task.version, NS)]
    lines.append("  <Triggers>")
    for trigger in task.triggers:
        lines.extend(_trigger_xml(trigger, 4))
    lines.append("  </Triggers>")
    lines.append("  <Settings>")
    lines.append(
        "    <MultipleInstancesPolicy>%s</MultipleInstancesPolicy>"
        % (task.multiple_instances or _DEFAULT_MULTIPLE_INSTANCES)
    )
    if not task.enabled:
        lines.append("    <Enabled>false</Enabled>")
    if task.execution_time_limit is not None and task.execution_time_limit > timedelta(0):
        lines.append(
            "    <ExecutionTimeLimit>%s</ExecutionTimeLimit>"
            % format_duration(task.execution_time_limit)
        )
    if task.random_delay:
        lines.append("    <RandomDelay>%s</RandomDelay>" % format_duration(task.random_delay))
    lines.append("  </Settings>")
    lines.append("</Task>")
    return "\n".join(lines) + "\n"

