        return False
    if trig.type == "time":
        return day == trig.start.date()
    raise AssertionError(trig.type)


def brute(task, start, end):
    """Independent, deliberately naive implementation of the spec."""
    if not task.enabled:
        return []
    runs = set()
    for trig in task.triggers:
        if not trig.enabled:
            continue
        day = trig.start.date()
        while day <= end.date():
            if matches(trig, day):
                occ = datetime.combine(day, trig.start.time())
                if occ >= trig.start and (trig.end is None or occ <= trig.end):
                    if trig.repetition is None:
                        if start < occ <= end:
                            runs.add(occ)
                    else:
                        k = 0
                        while True:
                            off = trig.repetition.interval * k
                            if trig.repetition.duration is not None and off >= trig.repetition.duration:
                                break
                            m = occ + off
                            if trig.end is not None and m > trig.end:
                                break
                            if m > end:
                                break
                            if m > start:
                                runs.add(m)
                            k += 1
            day += timedelta(days=1)
    return sorted(runs)


def compare_runs(label, got, want_all, count):
    """`want_all` is the (possibly truncated) brute-force list."""
    if len(want_all) >= count:
        want = want_all[:count]
        ok = got == want
    else:
        ok = got[:len(want_all)] == want_all
    if not ok:
        FAILS.append("%s\n   got  %r\n   want %r" % (label, got, want_all[:count]))


